pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        vm.assume(firstVal <= type(uint256).max - secondVal);
        c.SetMinSum(firstVal);
        c.SetMinSum(secondVal);
        // Rule: SetMinSum SETS the minimum sum; after the last call MinSum equals the last argument.
        assertTrue(c.MinSum() == secondVal);
    }
}

