pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        c.SetLogFile(logAddr);
        assertTrue(c.Log() == logAddr);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function run(uint v1, uint v2) public
    {
        require(address(this).balance >= v1 + v2);
        // point C's LogFile at this contract so log calls hit our payable fallback
        c.SetLogFile(address(this));
        c.Deposit{value: v1}();
        c.Deposit{value: v2}();
        assert(c.balances(address(this)) == v1 + v2);
    }

    receive() external payable {}

    fallback() external payable {}
}

